local function newOff(d)
	d = d or {}
	return { px = d.px or 0, py = d.py or 0, pz = d.pz or 0, rx = d.rx or 0, ry = d.ry or 0, rz = d.rz or 0,
		sx = d.sx or 1, sy = d.sy or 1, sz = d.sz or 1, sc = d.sc or 1 }
end
Config.Tweaks.Off = {}
