		local function interp(tb, z)
			if z <= tb[1][1] then return tb[1][2] end
			for i = 2, #tb do
				local a, b = tb[i - 1], tb[i]
				if z <= b[1] then return a[2] + (b[2] - a[2]) * (z - a[1]) / (b[1] - a[1]) end
