				local z2 = 7.5 + i * 0.3
				local t2 = bumpT(z2)
				add("FlareSkin", V(t2 + 0.02, 1.7, 0.33), P(sd * (face(z2) + t2 / 2), 2.4, z2), COLS.B, MATS.P, nil, 0, nil, 0.12)
