		for _, p in ipairs(parts) do
			if p.st then p.st.Color = col else p.f.BackgroundColor3 = col end
		end
		camT.setActive(camOn)
		if not camOn then
			dot.Size = UDim2.fromOffset(6, 6)
			rec.Visible = false
		end
	end
end
